/* Paratuberculose GDS 32-65 v1.1.0 — local-first PWA */
const APP_VERSION='1.1.0';
const DB_NAME='ptb_gds_32_65';
const DB_VERSION=1;
const STORES=['herds','campaigns','nonnegatives','descendants','introductions','animals','analysisLots','analysisTreatments','meta'];
const $=(s,r=document)=>r.querySelector(s); const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const digits=s=>String(s??'').replace(/\D/g,'');
const today=()=>new Date().toISOString().slice(0,10);
const fmtDate=v=>{if(!v)return''; const d=v instanceof Date?v:new Date(v); return isNaN(d)?String(v):d.toLocaleDateString('fr-FR')};
const num=v=>Number(String(v??'').replace(',','.'))||0;
const key=(...p)=>p.map(x=>String(x??'')).join('|');
function campaignFromDate(v){const d=v instanceof Date?v:new Date(v); if(isNaN(d))return''; const y=d.getFullYear(); return d.getMonth()>=6?`${y}/${y+1}`:`${y-1}/${y}`}
function currentCampaignDefault(){return campaignFromDate(new Date())}
function toast(msg){const t=$('#toast');t.textContent=msg;t.hidden=false;clearTimeout(toast._t);toast._t=setTimeout(()=>t.hidden=true,3200)}
function download(name,content,type='text/plain;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
function csvEscape(v){const s=String(v??''); return /[;"\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
function toCSV(rows,headers){return [headers.join(';'),...rows.map(r=>headers.map(h=>csvEscape(r[h])).join(';'))].join('\n')}

class IDBStore{
  constructor(){this.db=null}
  open(){return new Promise((res,rej)=>{const rq=indexedDB.open(DB_NAME,DB_VERSION);rq.onupgradeneeded=()=>{const db=rq.result;for(const s of STORES)if(!db.objectStoreNames.contains(s))db.createObjectStore(s,{keyPath:'id'})};rq.onsuccess=()=>{this.db=rq.result;res(this)};rq.onerror=()=>rej(rq.error)})}
  tx(store,mode='readonly'){return this.db.transaction(store,mode).objectStore(store)}
  all(store){return new Promise((res,rej)=>{const rq=this.tx(store).getAll();rq.onsuccess=()=>res(rq.result);rq.onerror=()=>rej(rq.error)})}
  get(store,id){return new Promise((res,rej)=>{const rq=this.tx(store).get(id);rq.onsuccess=()=>res(rq.result);rq.onerror=()=>rej(rq.error)})}
  put(store,obj){return new Promise((res,rej)=>{const rq=this.tx(store,'readwrite').put(obj);rq.onsuccess=()=>res(obj);rq.onerror=()=>rej(rq.error)})}
  bulkPut(store,arr){return new Promise((res,rej)=>{const tx=this.db.transaction(store,'readwrite'),os=tx.objectStore(store);arr.forEach(o=>os.put(o));tx.oncomplete=()=>res(arr.length);tx.onerror=()=>rej(tx.error)})}
  clear(store){return new Promise((res,rej)=>{const rq=this.tx(store,'readwrite').clear();rq.onsuccess=()=>res();rq.onerror=()=>rej(rq.error)})}
  delete(store,id){return new Promise((res,rej)=>{const rq=this.tx(store,'readwrite').delete(id);rq.onsuccess=()=>res();rq.onerror=()=>rej(rq.error)})}
}
const db=new IDBStore();
const state={view:'todo',campaign:'',herds:[],campaigns:[],nonnegatives:[],descendants:[],introductions:[],animals:[],analysisLots:[],analysisTreatments:[],meta:{},herdFilters:{q:'',dept:'',mode:''}};

async function loadState(){
  for(const s of ['herds','campaigns','nonnegatives','descendants','introductions','animals','analysisLots','analysisTreatments']) state[s]=await db.all(s);
  const meta=await db.all('meta'); state.meta=Object.fromEntries(meta.map(x=>[x.id,x.value]));
  state.campaign=state.meta.currentCampaign||currentCampaignDefault();
  if(!state.meta.currentCampaign)await setMeta('currentCampaign',state.campaign);
}
async function setMeta(id,value){state.meta[id]=value;await db.put('meta',{id,value})}

function getCampaignsList(){const set=new Set(state.campaigns.map(x=>x.campaign).filter(Boolean));set.add(state.campaign); return [...set].sort((a,b)=>b.localeCompare(a))}
function populateCampaignSelector(){const s=$('#globalCampaign');if(!s)return;s.innerHTML=getCampaignsList().map(c=>`<option ${c===state.campaign?'selected':''}>${esc(c)}</option>`).join('');}
function analysisAggregate(campaign=state.campaign){
  const map=new Map();
  for(const lot of state.analysisLots.filter(x=>x.campaign===campaign)){
    const k=String(lot.ede); if(!map.has(k))map.set(k,{ede:k,dept:lot.dept,campaign,lots:0,first:null,last:null,tested:0,positive:0,lastUpdate:null,dossiers:[]});
    const a=map.get(k);a.lots++; const d=lot.sampleDate?new Date(lot.sampleDate):null;if(d&&!isNaN(d)){if(!a.first||d<a.first)a.first=d;if(!a.last||d>a.last)a.last=d}
    a.tested+=num(lot.tested);a.positive+=num(lot.positive); const u=lot.lastUpdate?new Date(lot.lastUpdate):null;if(u&&!isNaN(u)&&(!a.lastUpdate||u>a.lastUpdate))a.lastUpdate=u;if(lot.labFile)a.dossiers.push(lot.labFile);
  }
  for(const a of map.values()){a.negative=Math.max(0,a.tested-a.positive);const t=state.analysisTreatments.find(x=>x.id===key(a.ede,campaign));const td=t?.treatmentDate?new Date(t.treatmentDate):null;const current=td&&a.lastUpdate&&td>=a.lastUpdate&&t.qualificationUpdated&&(a.positive===0||t.positivesManaged);a.status=current?'TRAITÉ':a.positive>0?'POSITIF À TRAITER':'À TRAITER';a.treatment=t||null}
  return map;
}
function animalIndex(){const m=new Map();for(const a of state.animals)m.set(String(a.animalId),a);return m}
function herdByEde(ede){return state.herds.find(h=>String(h.ede)===String(ede))}
function historyFor(ede){return state.campaigns.filter(c=>String(c.ede)===String(ede)).sort((a,b)=>String(b.campaign).localeCompare(String(a.campaign)))}
function activeAnimals(ede){return state.animals.filter(a=>String(a.ede)===String(ede))}

function render(){populateCampaignSelector(); $$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view)); const fn=views[state.view]||views.todo; $('#app').innerHTML=fn(); bindView()}
const pageHead=(title,sub='',actions='')=>`<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;
const badgeMode=m=>m?`<span class="badge ${norm(m).includes('garantie')?'garantie':'ass'}">${esc(m)}</span>`:'';

function thresholdFor(tested){const n=num(tested);return n<=50?1:n<=200?2:3}
function nextCampaign(c=state.campaign){const m=String(c||'').match(/^(\d{4})\/(\d{4})$/);return m?`${Number(m[1])+1}/${Number(m[2])+1}`:''}
function protocolYearValue(c,h){const raw=String(c?.protocolYear||'').match(/\d+/);if(raw)return Number(raw[0]);const hist=historyFor(h?.ede||c?.ede).filter(x=>x.protocol&&norm(x.protocol).includes('1 bis')).sort((a,b)=>String(a.campaign).localeCompare(String(b.campaign)));const idx=hist.findIndex(x=>x.campaign===state.campaign);return idx>=0?idx+1:0}
function isFavorableA(h,c){const q=norm([h?.currentQualification,h?.qualificationAgds,c?.status,c?.situation].join(' '));return q.includes('favorable')&&(!q.includes('intermediaire'))||/\ba\b/.test(q)||norm(h?.mode).includes('garantie')&&q.includes('qual')}
function screeningFor1Bis(year){if(year<=0)return'Tous bovins ≥ 24 mois - sérologie individuelle';if(year<=3)return'Tous bovins ≥ 24 mois - sérologie individuelle';if(year===4||year===6||year===8)return'Tous bovins de 24 à 72 mois - sérologie individuelle';return'Pas de dépistage de maintien programmé par le schéma 1 bis cette campagne (à confirmer selon historique)'}
function managementProposal(ede,analysis=null){
  const h=herdByEde(ede)||{ede};const c=state.campaigns.find(x=>String(x.ede)===String(ede)&&x.campaign===state.campaign)||{};const a=analysis||analysisAggregate().get(String(ede));const t=a?.treatment||{};const protocol=(c.protocol||h.protocol||'1 bis').trim();const year=protocolYearValue(c,h);const threshold=a?thresholdFor(a.tested):0;const maintenance=isFavorableA(h,c);const nxt=nextCampaign();
  const base={priority:3,label:'En attente',caseRef:'Référentiel statut favorable v3 - novembre 2025',qualification:'À confirmer',nextScreening:screeningFor1Bis(year?year+1:1),actions:[],note:'Proposition automatique à valider par le gestionnaire.'};
  if(!a){base.label='Résultats non reçus';base.actions=['Attendre / importer le résultat de la campagne.'];base.qualification=h.currentQualification||c.status||'Situation actuelle conservée';return base}
  if(a.positive===0){base.priority=3;base.label='Résultat favorable';base.caseRef='Référentiel statut favorable - surveillance des troupeaux';if(maintenance){base.qualification='Maintien du statut favorable (A), sous réserve du taux de réalisation et des autres exigences';base.nextScreening='Maintien : sérologie individuelle des 24-72 mois selon la fréquence applicable au troupeau.'}else if(norm(protocol).includes('1 bis')){if(year===1){base.qualification='Poursuite de l’acquisition - 1er contrôle favorable';base.nextScreening='N+1 : tous bovins ≥ 24 mois, sérologie individuelle.'}else if(year===2){base.qualification='Proposition : statut favorable intermédiaire (B)';base.nextScreening='N+1 : tous bovins ≥ 24 mois, sérologie individuelle (année 3).'}else if(year>=3){base.qualification='Proposition : statut favorable (A)';base.nextScreening='N+1 : bovins 24-72 mois, sérologie individuelle, puis maintien selon la fréquence du référentiel.'}else{base.qualification='Résultat favorable - vérifier l’ancienneté du protocole';}}
    base.actions=['Vérifier le taux de réalisation du dépistage.','Valider la qualification proposée dans les deux logiciels.'];return base
  }
  base.priority=1;base.label='POSITIF - gestion prioritaire';base.caseRef='Gestion des résultats non négatifs v2 - novembre 2025';
  const isolated=a.positive<=threshold;const pcr=t.pcrOutcome||'';const pcre=t.pcreOutcome||'';
  if(!pcr){if(isolated){base.actions=[`Nombre non négatif ≤ seuil (${threshold}) : situation potentiellement « isolée ».`,`Sous 15 à 30 jours : nouveau prélèvement sanguin + PCR sur fèces.`,`Dans l’attente : suspendre le statut et identifier/saisir les bovins non négatifs.`,`Si pas de recontrôle selon la procédure : bovin(s) considéré(s) infecté(s).`];base.qualification='Suspension en attente du recontrôle';base.caseRef='Résultats positifs/douteux en nombre « isolé » - § pages 4-5'}else{base.actions=[`Nombre de positifs > seuil (${threshold}) : hors procédure « isolée ».`,`Le résultat sérologique conclut d’emblée le(s) bovin(s) infecté(s).`,`PCR sur fèces dans les 30 jours après notification.`,`Appliquer ensuite le cas de gestion correspondant au statut/protocole du troupeau.`];base.qualification='Statut suspendu - gestion infectés à instruire';base.caseRef='Autres situations + bovins conclus infectés'}return base}
  if(maintenance){
    if(pcr==='negative'&&isolated){base.caseRef='Cas n°1-① - maintien A, ≤ seuil, PCR négative';base.qualification='Statut favorable réattribuable après réforme du/des infecté(s)';base.nextScreening='N+1 : tous bovins ≥ 24 mois en sérologie individuelle. N+2 : 24-72 mois, puis retour à la fréquence habituelle.';base.actions=['Isoler et réformer le(s) bovin(s) avant le début de N+1.','Exclure/réformer la descendance des campagnes N et N-1 avant fin N+1.']}
    else if(pcr==='positive'&&!isolated){base.caseRef='Cas n°1-② - maintien A, > seuil et ≥1 PCR positive';base.qualification='Retrait du statut - proposer un plan de maîtrise';base.nextScreening='Reprendre le processus de qualification au départ.';base.actions=['Réformer les bovins infectés.','Un statut A ou B ne pourra être attribué que si les infectés sont réformés avant le premier dépistage et ≥24 mois avant le dernier dépistage qualifiant.']}
    else{base.caseRef='Cas n°1-③ - situation intermédiaire en maintien A';base.qualification='Suspension ; réattribution possible après contrôle N+1 favorable et réformes réalisées';base.nextScreening='N+1 : tous ≥24 mois. N+2 : tous ≥24 mois. N+3 : 24-72 mois puis retour au rythme habituel.';base.actions=['Isoler/réformer les infectés avant N+1.','Réformer la descendance N et N-1 avant fin N+1.']}
    return base
  }
  if(norm(protocol).includes('1 bis')){
    if(year<=1){if(pcr==='negative'&&isolated){base.caseRef='Cas n°2a-① - acquisition 1/1bis année 1';base.qualification='Poursuite normale de l’acquisition';base.nextScreening='N+1 : 2e série, tous bovins ≥24 mois en sérologie individuelle.';base.actions=['Isoler/réformer les infectés avant N+1.','Réformer la descendance N et N-1 avant fin N+1.']}else{base.caseRef='Cas n°2a-② - acquisition année 1';base.qualification='Reprise du processus de qualification au départ / plan de maîtrise';base.nextScreening='Redémarrer l’acquisition après conditions de réforme prévues au référentiel.';base.actions=['Réformer les infectés.','Vérifier le délai de 24 mois avant le dernier dépistage qualifiant.']}return base}
    if(year===2||year===3){if(pcr==='negative'&&isolated){base.caseRef='Cas n°2c-① - référentiel 1 bis année 2 ou 3';base.qualification=year===2?'Proposition : statut favorable intermédiaire (B)':'Proposition : statut favorable (A)';base.nextScreening=year===2?'N+1 : année 3, tous bovins ≥24 mois.':'N+1 : démarrage du protocole de maintien.';base.actions=['Isoler/réformer les infectés avant N+1.','Réformer la descendance N et N-1 avant fin N+1.']}else if(!isolated){base.caseRef='Cas n°2c-② - référentiel 1 bis, nombre > seuil';base.qualification='Plan de maîtrise + reprise du processus au départ';base.nextScreening='Reprendre l’acquisition après les réformes/délais requis.';base.actions=['Réformer les infectés.']}else{base.caseRef='Cas n°2c-③ - référentiel 1 bis, ≤ seuil et ≥1 PCR positive';base.qualification='Acquisition prolongée sous conditions';base.nextScreening=year===2?'N+1 : tous ≥24 mois ; si favorable, B. N+2 : tous ≥24 mois ; si favorable, A.':'N+1 : tous ≥24 mois ; si favorable, A. Puis maintien.';base.actions=['Isoler/réformer les infectés avant N+1.','Réformer la descendance N et N-1 avant fin N+1.']}return base}
  }
  base.actions=['Le moteur reconnaît le référentiel mais ce cas nécessite encore une validation manuelle détaillée.'];base.qualification='À valider';return base
}
function decisionHTML(p){const cls=p.priority===1?'high':p.priority===2?'medium':p.label.includes('favorable')?'good':'';return`<div class="decision ${cls}"><h3><span class="smart-tag">Référentiel intelligent</span> ${esc(p.label)}</h3><div><b>Qualification proposée :</b> ${esc(p.qualification)}</div><div><b>N+1 proposé :</b> ${esc(p.nextScreening)}</div>${p.actions?.length?`<ul>${p.actions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<small>Cas : ${esc(p.caseRef)}. ${esc(p.note||'')} <a class="ref-link" target="_blank" href="./referentiel/Gestion_resultats_non_negatifs_v2_nov2025.pdf">Ouvrir le référentiel</a></small></div>`}
function priorityScore(a){if(a.status==='TRAITÉ')return 99;if(a.positive>0)return 0;return 1}
function priorityList(){const rows=[...analysisAggregate().values()].sort((a,b)=>priorityScore(a)-priorityScore(b)||String(a.lastUpdate).localeCompare(String(b.lastUpdate)));if(!rows.length)return'<div class="empty">Aucun résultat importé pour cette campagne.</div>';return`<div class="priority-list">${rows.map(a=>{const p=managementProposal(a.ede,a);const cls=a.status==='TRAITÉ'?'done':a.positive>0?'':'p2';return`<div class="priority-item ${cls}"><div class="priority-bar"></div><div class="priority-body"><div class="priority-title"><span>${esc(herdByEde(a.ede)?.name||a.ede)}</span><span class="badge ${a.positive>0?'red':'yellow'}">${a.positive>0?`${a.positive} positif(s)`:'Résultat à valider'}</span></div><div class="priority-meta">EDE ${esc(a.ede)} · ${a.tested} dépistés · ${a.negative} négatifs · ${fmtDate(a.last)} · ${esc(p.caseRef)}</div><div class="mini">${esc(p.qualification)} · N+1 : ${esc(p.nextScreening)}</div></div><div class="priority-action"><button class="primary" data-herd="${esc(a.ede)}">Ouvrir</button></div></div>`}).join('')}</div>`}
function campaignStatus(c,a){if(a){if(a.status==='TRAITÉ')return'<span class="status-dot received"></span>Traité';if(a.positive>0)return'<span class="status-dot positive"></span>Positif à traiter';return'<span class="status-dot todo"></span>Reçu - à valider'}return'<span class="status-dot"></span>Résultat non reçu'}
function pie(value,total,c1='#8e2c6d',c2='#e7eaec'){const pct=total?Math.max(0,Math.min(100,value/total*100)):0;return`<div class="pie" style="background:conic-gradient(${c1} 0 ${pct}%,${c2} ${pct}% 100%)"></div>`}

const views={
 todo(){const ag=[...analysisAggregate().values()],pos=ag.filter(x=>x.positive>0).length,todo=ag.filter(x=>x.status!=='TRAITÉ').length;return pageHead('À traiter',`Priorités - campagne ${esc(state.campaign)}`,`<button class="primary" data-go="imports">Importer des résultats</button>`)+`<div class="grid kpi-grid">${kpi('Résultats reçus',ag.length,`${state.herds.length} engagés`)}${kpi('À traiter',todo,'dossiers ouverts')}${kpi('Cheptels positifs',pos,'priorité haute')}${kpi('Traités',ag.filter(x=>x.status==='TRAITÉ').length,'validés')}</div><div class="card"><h2>File de traitement</h2><p class="help">Les positifs sont placés en tête. La proposition de gestion s’appuie sur les référentiels novembre 2025 et doit être validée avant application.</p>${priorityList()}</div>`},
 campaigns(){const rows=state.campaigns.filter(c=>c.campaign===state.campaign),ag=analysisAggregate();const merged=rows.map(c=>({...c,analysis:ag.get(String(c.ede))}));return pageHead('Campagne',`Suivi de tous les engagés - ${esc(state.campaign)}`,`<button class="primary" data-go="imports">Importer</button>`)+`<div class="toolbar"><input id="campaignQ" type="search" placeholder="EDE, éleveur, mode, statut…"><select id="campaignResult"><option value="">Tous</option><option value="missing">Résultat non reçu</option><option value="received">Résultat reçu</option><option value="positive">Positif</option><option value="todo">À traiter</option></select></div><div id="campaignTable">${campaignTableHTML(merged)}</div>`},
 herds(){const f=state.herdFilters,rows=filteredHerds();return pageHead('Éleveurs',`${rows.length} cheptel(s)`,``)+`<div class="toolbar"><input id="herdQ" type="search" placeholder="EDE, nom, commune, vétérinaire…" value="${esc(f.q)}"><select id="herdDept"><option value="">32 + 65</option><option ${f.dept==='32'?'selected':''}>32</option><option ${f.dept==='65'?'selected':''}>65</option></select><select id="herdMode"><option value="">Garantie + Assainissement</option><option ${f.mode==='Garantie'?'selected':''}>Garantie</option><option ${f.mode==='Assainissement'?'selected':''}>Assainissement</option></select></div>${herdTable(rows)}`},
 herdDetail(){return herdDetailHTML(state.selectedHerd)},
 imports(){return pageHead('Imports','Les fichiers bruts sont reconnus directement',`<button class="primary" id="btnImportBundled">Charger l’historique fourni</button>`)+`<div class="grid split"><div>${importCard('migration','Historique initial Excel','Migration CHEPTELS, CAMPAGNES, NON_NEGATIFS, DESCENDANTS et INTRODUCTIONS.','.xlsx,.xls')}${importCard('animals32','Animaux 32','Export bovins brut du 32. Met à jour présence, sorties, mères et descendants.','.csv')}${importCard('animals65','Animaux 65','Export bovins brut du 65.','.csv')}</div><div>${importCard('analysis32','Analyses 32','Export analyses exploitation détaillé du 32. Agrégation automatique des lots par EDE/campagne.','.csv')}${importCard('analysis65','Analyses 65','Export analyses exploitation détaillé du 65.','.csv')}<div class="card"><h3>Après import</h3><p class="help">La file « À traiter » est reconstruite automatiquement. Les numéros individuels des non négatifs restent saisis dans la fiche éleveur, car l’export d’analyses exploitation ne les contient pas.</p></div></div></div>`},
 exports(){return pageHead('Exports','Listes d’engagés et de bovins')+`<div class="grid split"><div class="card"><h2>Engagés</h2><div class="actions"><button class="primary export-btn" data-export="engages">Tous les engagés</button><button class="ghost export-btn" data-export="garantie">Garantie</button><button class="ghost export-btn" data-export="ass">Assainissement</button><button class="ghost export-btn" data-export="garantie32">Garantie 32</button><button class="ghost export-btn" data-export="garantie65">Garantie 65</button><button class="ghost export-btn" data-export="ass32">Assainissement 32</button><button class="ghost export-btn" data-export="ass65">Assainissement 65</button></div></div><div class="card"><h2>Bovins</h2><div class="actions"><button class="primary export-btn" data-export="animalsPresent">Bovins présents des engagés</button><button class="ghost export-btn" data-export="animalsAll">Tous bovins chargés</button><button class="ghost export-btn" data-export="nonnegpresent">Non négatifs présents</button><button class="ghost export-btn" data-export="descendants">Descendants</button></div></div></div><div class="card"><h2>Suivi campagne</h2><div class="actions"><button class="ghost export-btn" data-export="positifs">Cheptels positifs</button><button class="ghost export-btn" data-export="campaignFollowup">Suivi de tous les engagés</button><button class="ghost export-btn" data-export="introductions">Introductions</button></div></div>`},
 balance(){const b=balance(),received=b.herdsTested,missing=Math.max(0,b.herds-received);return pageHead('Bilan & récap',`Campagne ${esc(state.campaign)}`,`<button class="primary export-btn" data-export="bilan">Exporter le bilan CSV</button>`)+`<div class="grid kpi-grid">${kpi('Engagés',b.herds,'32 + 65')}${kpi('Résultats reçus',received,`${missing} non reçus`)}${kpi('Cheptels positifs',b.positiveHerds,`${b.positiveAnalyses} bovin(s) positif(s)`)}${kpi('À traiter',b.toTreat,'campagne active')}</div><div class="charts"><div class="chart-card">${pie(b.guarantee,b.herds)}<div class="legend"><b>${b.guarantee}</b><br>Garantie<br>${b.assainissement} Assainissement</div></div><div class="chart-card">${pie(received,b.herds,'#43a047','#eceff1')}<div class="legend"><b>${received}</b><br>résultats reçus<br>${missing} en attente</div></div><div class="chart-card">${pie(b.positiveHerds,Math.max(received,1),'#c62828','#e8f5e9')}<div class="legend"><b>${b.positiveHerds}</b><br>cheptels positifs<br>${Math.max(0,received-b.positiveHerds)} sans positif</div></div></div><div class="card" style="margin-top:14px"><h2>Référentiels intégrés</h2><div class="ref-grid"><div class="ref-card"><b>Statut favorable bovin</b><p class="help">Règles d’acquisition, maintien, mouvements et protocoles.</p><a class="ref-link" target="_blank" href="./referentiel/Referentiel_statut_favorable_v3_nov2025.pdf">Ouvrir - version 3, novembre 2025</a></div><div class="ref-card"><b>Gestion des résultats non négatifs</b><p class="help">Seuils, recontrôles, suspects/infectés et cas de gestion.</p><a class="ref-link" target="_blank" href="./referentiel/Gestion_resultats_non_negatifs_v2_nov2025.pdf">Ouvrir - version 2, novembre 2025</a></div></div></div>`},
 settings(){return pageHead('Paramètres','Campagne active, sauvegardes et synchronisation')+`<div class="card"><h2>Campagne active</h2><div class="form-grid"><div class="field"><label>Campagne</label><input id="settingCampaign" value="${esc(state.campaign)}" placeholder="2026/2027"></div><div class="field"><label>&nbsp;</label><button class="primary" id="saveCampaign">Enregistrer</button></div></div></div><div class="card"><h2>Supabase (optionnel)</h2><p class="help">Le logiciel fonctionne localement. Pour plusieurs postes, renseigner l’URL et la clé publique Supabase.</p><div class="form-grid"><div class="field"><label>URL Supabase</label><input id="sbUrl" value="${esc(state.meta.supabaseUrl||'')}"></div><div class="field"><label>Clé publique / anon</label><input id="sbKey" type="password" value="${esc(state.meta.supabaseKey||'')}"></div></div><div class="actions" style="margin-top:12px"><button class="primary" id="saveSupabase">Enregistrer</button><button class="ghost" id="pushSupabase">Envoyer</button><button class="ghost" id="pullSupabase">Récupérer</button></div></div><div class="card"><h2>Sauvegarde / restauration</h2><div class="actions"><button class="ghost" id="restoreJsonBtn">Restaurer JSON</button><input id="restoreJsonInput" type="file" accept=".json" hidden><button class="danger" id="resetDbBtn">Réinitialiser les données locales</button></div></div>`}
};
function campaignTableHTML(rows){if(!rows.length)return'<div class="empty">Aucun engagé pour cette campagne.</div>';return`<div class="table-wrap"><table><thead><tr><th>EDE</th><th>Éleveur</th><th>Mode</th><th>Dépistage prévu</th><th>Résultat</th><th>Dépistés</th><th>+ / -</th><th>Qualification proposée</th><th>N+1 proposé</th></tr></thead><tbody>${rows.map(c=>{const h=herdByEde(c.ede),a=c.analysis,p=managementProposal(c.ede,a);const cls=a?.positive?'positive':a?.status==='TRAITÉ'?'treated':'waiting';return`<tr class="click-row campaign-row ${cls}" data-herd="${esc(c.ede)}"><td><strong>${esc(c.ede)}</strong></td><td>${esc(h?.name||c.name||'')}</td><td>${badgeMode(h?.mode||c.mode)}</td><td>${esc(c.screeningPlanned||p.nextScreening||'')}</td><td>${campaignStatus(c,a)}</td><td>${a?a.tested:esc(c.tested||'')}</td><td>${a?`${a.positive} / ${a.negative}`:''}</td><td>${esc(p.qualification)}</td><td>${esc(p.nextScreening)}</td></tr>`}).join('')}</tbody></table></div>`}
function herdDetailHTML(ede){if(!ede)return pageHead('Éleveur','Aucun dossier sélectionné');const h=herdByEde(ede)||{ede};const hist=historyFor(ede),animals=activeAnimals(ede),nn=state.nonnegatives.filter(x=>String(x.ede)===String(ede)),desc=state.descendants.filter(x=>String(x.ede)===String(ede)),intro=state.introductions.filter(x=>String(x.ede)===String(ede)),a=analysisAggregate().get(String(ede)),p=managementProposal(ede,a);return`<button class="ghost back-btn" id="backToHerds">← Retour</button><div class="herd-head"><div>${pageHead(h.name||'Éleveur',`EDE ${esc(ede)} · département ${esc(h.dept||'')}`)}</div><div class="stat-line">${badgeMode(h.mode)}<span class="stat-pill">${esc(h.currentQualification||'Qualification non renseignée')}</span></div></div><div class="section-nav"><a href="#situation">Situation</a><a href="#analyses">Analyses</a><a href="#nonneg">Non négatifs (${nn.length})</a><a href="#desc">Descendants (${desc.length})</a><a href="#animals">Animaux (${animals.length})</a><a href="#history">Historique</a></div><section id="situation" class="herd-section card"><h2>Situation actuelle</h2><div class="form-grid"><div><b>Vétérinaire</b><br>${esc(h.vet||'')}</div><div><b>Protocole</b><br>${esc(h.protocol||'1 bis')}</div><div><b>Qualification AGDS</b><br>${esc(h.qualificationAgds||h.currentQualification||'')}</div><div><b>Qualification nationale</b><br>${esc(h.qualificationNational||'')}</div></div>${decisionHTML(p)}</section><section id="analyses" class="herd-section card"><h2>Analyses - ${esc(state.campaign)}</h2>${a?analysisTable([a]):'<div class="empty">Aucun résultat reçu pour cette campagne.</div>'}</section><section id="nonneg" class="herd-section card"><div class="page-head"><div><h2>Non négatifs</h2></div><button class="primary" id="btnAddNNForHerd">+ Ajouter</button></div>${nonNegTableForHerd(nn)}</section><section id="desc" class="herd-section card"><h2>Descendants</h2>${simpleObjectTable(desc,['animalId','motherId','birthDate','presence','exitDate','exitCause'])}</section><section id="animals" class="herd-section card"><h2>Animaux</h2>${animalTable(animals.slice(0,500))}</section><section id="history" class="herd-section card"><h2>Historique campagnes</h2><div class="timeline">${hist.map(c=>`<div class="event"><strong>${esc(c.campaign)}</strong><small>${esc(c.status||c.situation||'')}</small><p>${esc(c.method||c.screeningPlanned||'')}</p><small>${c.tested?`${c.tested} dépistés · ${c.positive||0} positifs`:''}</small></div>`).join('')||'<div class="empty">Pas d’historique.</div>'}</div></section>`}
function nonNegTableForHerd(rows){const ai=animalIndex();if(!rows.length)return'<div class="empty">Aucun non négatif enregistré.</div>';return`<div class="table-wrap"><table><thead><tr><th>Campagne</th><th>Animal</th><th>Nom / travail</th><th>Résultat</th><th>Date</th><th>PCR</th><th>Conclusion</th><th>Présence</th><th>Sortie</th></tr></thead><tbody>${rows.map(n=>{const a=ai.get(String(n.animalId));return`<tr><td>${esc(n.campaign||'')}</td><td>${esc(n.animalId)}</td><td>${esc(a?.name||n.name||'')} ${a?.workNo?`(${esc(a.workNo)})`:''}</td><td>${esc(n.result||'')}</td><td>${fmtDate(n.date)}</td><td>${esc(n.pcrResult||'')}</td><td>${esc(n.conclusion||'')}</td><td>${esc(a?.presence||n.presence||'')}</td><td>${fmtDate(a?.exitDate||n.exitDate)}</td></tr>`}).join('')}</tbody></table></div>`}

function kpi(label,value,sub=''){return`<div class="kpi"><div class="label">${esc(label)}</div><div class="value">${esc(value)}</div><div class="sub">${esc(sub)}</div></div>`}
function statusBadge(s){return`<span class="badge ${s==='POSITIF À TRAITER'?'red':s==='À TRAITER'?'yellow':'green'}">${esc(s)}</span>`}
function analysisTable(rows){if(!rows.length)return'<div class="empty">Aucune analyse pour cette campagne.</div>';return`<div class="table-wrap"><table><thead><tr><th>EDE</th><th>Éleveur</th><th>Lots</th><th>Prélèvement</th><th>Dépistés</th><th>Négatifs</th><th>Positifs</th><th>Dernière MAJ</th><th>Statut</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td>${esc(a.ede)}</td><td class="click-row" data-herd="${esc(a.ede)}">${esc(herdByEde(a.ede)?.name||'')}</td><td>${a.lots}</td><td>${fmtDate(a.last)}</td><td>${a.tested}</td><td>${a.negative}</td><td><strong>${a.positive}</strong></td><td>${fmtDate(a.lastUpdate)}</td><td>${statusBadge(a.status)}</td><td><button class="ghost analysis-treat" data-ede="${esc(a.ede)}">Traiter</button></td></tr>`).join('')}</tbody></table></div>`}
function filteredHerds(){const f=state.herdFilters;return state.herds.filter(h=>{const hay=norm([h.ede,h.name,h.commune,h.vet,h.mode,h.currentQualification].join(' '));return(!f.q||hay.includes(norm(f.q)))&&(!f.dept||String(h.dept)===f.dept)&&(!f.mode||norm(h.mode).includes(norm(f.mode)))})}
function herdTable(rows){if(!rows.length)return'<div class="empty">Aucun cheptel.</div>';return`<div class="table-wrap"><table><thead><tr><th>Dépt</th><th>EDE</th><th>Éleveur</th><th>Commune</th><th>Mode</th><th>Qualification actuelle</th><th>Vétérinaire</th></tr></thead><tbody>${rows.map(h=>`<tr class="click-row" data-herd="${esc(h.ede)}"><td>${esc(h.dept)}</td><td><strong>${esc(h.ede)}</strong></td><td>${esc(h.name)}</td><td>${esc(h.commune||'')}</td><td>${badgeMode(h.mode)}</td><td>${esc(h.currentQualification||h.qualification||'')}</td><td>${esc(h.vet||'')}</td></tr>`).join('')}</tbody></table></div>`}
function animalTable(rows){if(!rows.length)return'<div class="empty">Aucun animal.</div>';return`<div class="table-wrap"><table><thead><tr><th>Animal</th><th>Travail</th><th>Nom</th><th>EDE</th><th>Sexe</th><th>Naissance</th><th>Présence</th><th>Date sortie</th><th>Cause</th><th>Mère</th></tr></thead><tbody>${rows.map(a=>`<tr class="click-row" data-herd="${esc(a.ede)}"><td>${esc(a.animalId)}</td><td>${esc(a.workNo||'')}</td><td>${esc(a.name||'')}</td><td>${esc(a.ede)}</td><td>${esc(a.sex||'')}</td><td>${fmtDate(a.birthDate)}</td><td>${esc(a.presence||'')}</td><td>${fmtDate(a.exitDate)}</td><td>${esc(a.exitCause||'')}</td><td>${esc(a.motherId||'')}</td></tr>`).join('')}</tbody></table></div>`}
function simpleObjectTable(rows,cols){if(!rows.length)return'<div class="empty">Aucune donnée.</div>';return`<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${esc(r[c]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function importCard(id,title,help,accept){return`<div class="card"><h2>${title}</h2><p class="help">${help}</p><div class="dropzone" data-drop="${id}"><label for="file_${id}">Choisir le fichier</label><input id="file_${id}" data-import="${id}" type="file" accept="${accept}"><div class="help" style="margin-top:8px">ou glisser-déposer ici</div></div></div>`}
function balance(){const ag=[...analysisAggregate().values()];return{campaign:state.campaign,herds:state.herds.length,guarantee:state.herds.filter(h=>norm(h.mode).includes('garantie')).length,assainissement:state.herds.filter(h=>norm(h.mode).includes('assain')).length,herdsTested:ag.length,animalsTested:ag.reduce((s,x)=>s+x.tested,0),positiveHerds:ag.filter(x=>x.positive>0).length,positiveAnalyses:ag.reduce((s,x)=>s+x.positive,0),toTreat:ag.filter(x=>x.status!=='TRAITÉ').length}}
function balanceHTML(){const b=balance();return`<div class="stat-line"><span class="stat-pill">${b.herds} engagés</span><span class="stat-pill">${b.guarantee} Garantie</span><span class="stat-pill">${b.assainissement} Assainissement</span><span class="stat-pill">${b.herdsTested} dépistés</span><span class="stat-pill">${b.animalsTested} bovins analysés</span><span class="stat-pill">${b.positiveHerds} cheptels positifs</span><span class="stat-pill">${b.positiveAnalyses} positifs</span></div>`}

function bindView(){
  $$('[data-go]').forEach(b=>b.onclick=()=>{state.view=b.dataset.go;render()});
  $$('[data-herd]').forEach(r=>r.onclick=()=>openHerd(r.dataset.herd));
  $$('.analysis-treat').forEach(b=>b.onclick=e=>{e.stopPropagation();openTreatment(b.dataset.ede)});
  if($('#herdQ')) $('#herdQ').oninput=e=>{state.herdFilters.q=e.target.value;$('#app').innerHTML=views.herds();bindView()};
  if($('#herdDept')) $('#herdDept').onchange=e=>{state.herdFilters.dept=e.target.value;render()};
  if($('#herdMode')) $('#herdMode').onchange=e=>{state.herdFilters.mode=e.target.value;render()};
  if($('#campaignQ')) $('#campaignQ').oninput=applyCampaignFilters;
  if($('#campaignResult')) $('#campaignResult').onchange=applyCampaignFilters;
  $$('[data-import]').forEach(i=>i.onchange=()=>i.files[0]&&handleImport(i.dataset.import,i.files[0]));
  $$('[data-drop]').forEach(z=>{z.ondragover=e=>{e.preventDefault();z.classList.add('drag')};z.ondragleave=()=>z.classList.remove('drag');z.ondrop=e=>{e.preventDefault();z.classList.remove('drag');const f=e.dataTransfer.files[0];if(f)handleImport(z.dataset.drop,f)}});
  $$('.export-btn').forEach(b=>b.onclick=()=>runExport(b.dataset.export));
  if($('#btnImportBundled')) $('#btnImportBundled').onclick=importBundledHistory;
  if($('#btnAddNNForHerd')) $('#btnAddNNForHerd').onclick=()=>openNNForm(state.selectedHerd);
  if($('#backToHerds')) $('#backToHerds').onclick=()=>{state.view='herds';render()};
  if($('#saveCampaign')) $('#saveCampaign').onclick=async()=>{const v=$('#settingCampaign').value.trim();if(!/^\d{4}\/\d{4}$/.test(v))return toast('Format attendu : 2026/2027');state.campaign=v;await setMeta('currentCampaign',v);render();toast('Campagne enregistrée')};
  if($('#saveSupabase')) $('#saveSupabase').onclick=async()=>{await setMeta('supabaseUrl',$('#sbUrl').value.trim().replace(/\/$/,''));await setMeta('supabaseKey',$('#sbKey').value.trim());toast('Paramètres Supabase enregistrés')};
  if($('#pushSupabase')) $('#pushSupabase').onclick=pushSupabase;
  if($('#pullSupabase')) $('#pullSupabase').onclick=pullSupabase;
  if($('#restoreJsonBtn')) $('#restoreJsonBtn').onclick=()=>$('#restoreJsonInput').click();
  if($('#restoreJsonInput')) $('#restoreJsonInput').onchange=e=>restoreBackup(e.target.files[0]);
  if($('#resetDbBtn')) $('#resetDbBtn').onclick=resetDb;
}
function applyCampaignFilters(){const q=norm($('#campaignQ')?.value||''),f=$('#campaignResult')?.value||'',ag=analysisAggregate();let rows=state.campaigns.filter(c=>c.campaign===state.campaign).map(c=>({...c,analysis:ag.get(String(c.ede))}));rows=rows.filter(c=>{const h=herdByEde(c.ede),a=c.analysis;const hay=norm([c.ede,h?.name,c.mode,h?.mode,c.status,c.screeningPlanned].join(' '));if(q&&!hay.includes(q))return false;if(f==='missing'&&a)return false;if(f==='received'&&!a)return false;if(f==='positive'&&!(a&&a.positive>0))return false;if(f==='todo'&&!(a&&a.status!=='TRAITÉ'))return false;return true});$('#campaignTable').innerHTML=campaignTableHTML(rows);$$('[data-herd]',$('#campaignTable')).forEach(r=>r.onclick=()=>openHerd(r.dataset.herd))}

function openModal(html){$('#modalBody').innerHTML=html;$('#modal').hidden=false}
function closeModal(){$('#modal').hidden=true;$('#modalBody').innerHTML=''}
$('#modalClose').onclick=closeModal;$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal()};
function openHerd(ede){state.selectedHerd=String(ede);state.view='herdDetail';render()}
function openTreatment(ede){const a=analysisAggregate().get(String(ede));const t=a?.treatment||{};const p=managementProposal(ede,a);openModal(`<h2>Traitement analyse - ${esc(ede)}</h2><p>${a?.tested||0} dépistés · ${a?.positive||0} positif(s) · dernière MAJ ${fmtDate(a?.lastUpdate)}</p>${decisionHTML(p)}<div class="form-grid"><div class="field"><label>Résultat PCR des bovins concernés</label><select id="trPcr"><option value="">Non renseigné</option><option value="negative" ${t.pcrOutcome==='negative'?'selected':''}>Toutes PCR négatives</option><option value="positive" ${t.pcrOutcome==='positive'?'selected':''}>Au moins une PCR positive</option></select></div><div class="field"><label>Résultat PCRe (si applicable)</label><select id="trPcre"><option value="">Non applicable / inconnu</option><option value="negative" ${t.pcreOutcome==='negative'?'selected':''}>Négative</option><option value="positive_gt32" ${t.pcreOutcome==='positive_gt32'?'selected':''}>Positive Ct &gt; 32</option><option value="positive_lt32" ${t.pcreOutcome==='positive_lt32'?'selected':''}>Positive Ct &lt; 32</option></select></div><div class="field"><label>Date de traitement</label><input id="trDate" type="date" value="${esc(t.treatmentDate||today())}"></div><div class="field"><label>Qualification mise à jour ?</label><select id="trQual"><option value="false">Non</option><option value="true" ${t.qualificationUpdated?'selected':''}>Oui</option></select></div><div class="field"><label>Positifs gérés ?</label><select id="trPos"><option value="false">Non</option><option value="true" ${t.positivesManaged?'selected':''}>Oui</option></select></div><div class="field"><label>Commentaire / décision validée</label><textarea id="trCom">${esc(t.comment||'')}</textarea></div></div><div class="actions"><button class="primary" id="recalcTreatment">Recalculer la proposition</button><button class="primary" id="saveTreatment">Enregistrer</button></div>`);$('#recalcTreatment').onclick=async()=>{const tmp={...t,id:key(ede,state.campaign),ede:String(ede),campaign:state.campaign,pcrOutcome:$('#trPcr').value,pcreOutcome:$('#trPcre').value};const existing=state.analysisTreatments.findIndex(x=>x.id===tmp.id);const old=existing>=0?state.analysisTreatments[existing]:null;if(existing>=0)state.analysisTreatments[existing]=tmp;else state.analysisTreatments.push(tmp);closeModal();openTreatment(ede);if(old)state.analysisTreatments[existing]=old;else state.analysisTreatments=state.analysisTreatments.filter(x=>x!==tmp)};$('#saveTreatment').onclick=async()=>{const obj={id:key(ede,state.campaign),ede:String(ede),campaign:state.campaign,pcrOutcome:$('#trPcr').value,pcreOutcome:$('#trPcre').value,treatmentDate:$('#trDate').value,qualificationUpdated:$('#trQual').value==='true',positivesManaged:$('#trPos').value==='true',comment:$('#trCom').value,updatedAt:new Date().toISOString()};await db.put('analysisTreatments',obj);state.analysisTreatments=await db.all('analysisTreatments');closeModal();render();toast('Traitement enregistré')};}

function openNNForm(defaultEde=''){openModal(`<h2>Ajouter un non négatif</h2><div class="form-grid"><div class="field"><label>EDE</label><input id="nnEde" value="${esc(defaultEde)}"></div><div class="field"><label>Animal</label><input id="nnAnimal"></div><div class="field"><label>Campagne</label><input id="nnCamp" value="${esc(state.campaign)}"></div><div class="field"><label>Résultat sérologique</label><select id="nnRes"><option>Positif</option><option>Douteux</option><option>Non négatif</option></select></div><div class="field"><label>PCR fèces</label><select id="nnPcr"><option value="">Non faite / inconnue</option><option>Négative</option><option>Positive</option></select></div><div class="field"><label>Conclusion</label><select id="nnConclusion"><option value="">À conclure</option><option>Présumé non infecté</option><option>Suspect</option><option>Infecté</option></select></div><div class="field"><label>Date</label><input id="nnDate" type="date" value="${today()}"></div><div class="field"><label>Commentaire</label><textarea id="nnCom"></textarea></div></div><button class="primary" id="saveNN">Enregistrer</button>`);$('#saveNN').onclick=async()=>{const ede=$('#nnEde').value.trim(),animalId=digits($('#nnAnimal').value);if(!ede||!animalId)return toast('EDE et animal obligatoires');const obj={id:key($('#nnCamp').value,ede,animalId,$('#nnDate').value),campaign:$('#nnCamp').value,ede,animalId,result:$('#nnRes').value,pcrResult:$('#nnPcr').value,conclusion:$('#nnConclusion').value,date:$('#nnDate').value,comment:$('#nnCom').value};await db.put('nonnegatives',obj);state.nonnegatives=await db.all('nonnegatives');closeModal();render();toast('Non négatif enregistré')};}


async function importBundledHistory(){try{toast('Chargement de l’historique fourni…');const r=await fetch('./migration/Suivi_Paratuberculose_32_65_V9_1_final_sans_analyses.xlsx');if(!r.ok)throw new Error('Fichier historique introuvable');const blob=await r.blob();const f=new File([blob],'historique_V9_1.xlsx',{type:blob.type||'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});await importExcel(f);await loadState();render();toast('Historique chargé')}catch(e){console.error(e);toast('Historique : '+e.message)}}
async function handleImport(type,file){try{toast(`Import de ${file.name}…`);if(type==='migration')await importExcel(file);else if(type.startsWith('animals'))await importAnimals(file,type.endsWith('32')?32:65);else await importAnalysis(file,type.endsWith('32')?32:65);await loadState();render();toast('Import terminé')}catch(e){console.error(e);toast('Erreur import : '+e.message)}}
function readFile(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsArrayBuffer(file)})}
function sheetObjects(wb,name){const sh=wb.Sheets[name];if(!sh)return[];return XLSX.utils.sheet_to_json(sh,{defval:'',raw:false,dateNF:'dd/mm/yyyy'})}
function pick(o,...keys){for(const k of keys){const found=Object.keys(o).find(x=>norm(x)===norm(k));if(found!==undefined&&o[found]!==''&&o[found]!=null)return o[found]}return''}
function parseFrenchDate(v){if(!v)return'';if(v instanceof Date)return v.toISOString();const m=String(v).match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);return m?new Date(+m[3],+m[2]-1,+m[1]).toISOString():v}
async function importExcel(file){if(!window.XLSX)throw new Error('Bibliothèque Excel indisponible : connexion internet nécessaire au premier import.');const data=await readFile(file),w=XLSX.read(data,{type:'array',cellDates:true});
  const herds=sheetObjects(w,'CHEPTELS').map((r,i)=>{const ede=digits(pick(r,'N° cheptel','N° EDE','N° cheptel / EDE'));return{id:ede||`herd${i}`,ede,dept:Number(pick(r,'Dépt','Département'))||Number(ede.slice(0,2)),name:pick(r,'Nom','Éleveur'),commune:pick(r,'Commune'),mode:pick(r,'Mode suivi','Mode de suivi'),protocol:pick(r,'Protocole'),vet:pick(r,'Vétérinaire'),currentQualification:pick(r,'Qualification actuelle','Situation garantie','Qualification AGDS'),qualificationAgds:pick(r,'Qualification AGDS'),qualificationNational:pick(r,'Qualification logiciel national'),raw:r}}).filter(x=>x.ede);
  const campaigns=sheetObjects(w,'CAMPAGNES').map((r,i)=>{const ede=digits(pick(r,'N° cheptel','N° EDE'));const camp=pick(r,'Campagne');return{id:key(camp,ede,i),campaign:camp,ede,dept:Number(pick(r,'Dépt')),name:pick(r,'Nom'),mode:pick(r,'Mode suivi'),situation:pick(r,'Situation garantie'),protocol:pick(r,'Protocole'),protocolYear:pick(r,'Année protocole / ancienneté'),screeningPlanned:pick(r,'Dépistage prévu'),method:pick(r,'Méthode'),tested:num(pick(r,'Nb dépistés')),negative:num(pick(r,'Nb négatifs')),positive:num(pick(r,'Nb positifs')),status:pick(r,'Qualif / statut campagne'),campaignDate:parseFrenchDate(pick(r,'Date campagne')),comment:pick(r,'Commentaires / source'),raw:r}}).filter(x=>x.ede&&x.campaign);
  const nns=sheetObjects(w,'NON_NEGATIFS').map((r,i)=>{const ede=digits(pick(r,'N° cheptel','N° EDE')),animalId=digits(pick(r,'N° bovin','Animal','Identifiant bovin'));const camp=pick(r,'Campagne');return{id:key(camp,ede,animalId,i),campaign:camp,dept:Number(pick(r,'Dépt')),ede,animalId,result:pick(r,'Résultat'),date:parseFrenchDate(pick(r,'Date','Date résultat')),presence:pick(r,'Présent / sorti','Présence'),exitDate:parseFrenchDate(pick(r,'Date sortie')),exitCause:pick(r,'Cause sortie'),comment:pick(r,'Commentaires','Commentaire'),raw:r}}).filter(x=>x.ede&&x.animalId);
  const desc=sheetObjects(w,'DESCENDANTS').map((r,i)=>{const ede=digits(pick(r,'N° cheptel','N° EDE')),animalId=digits(pick(r,'N° descendant','N° bovin','Animal'));return{id:key(ede,animalId,i),dept:Number(pick(r,'Dépt')),ede,motherId:digits(pick(r,'N° mère positive','N° mère')),animalId,birthDate:parseFrenchDate(pick(r,'Date naissance')),presence:pick(r,'Présent / sorti','Présence'),exitDate:parseFrenchDate(pick(r,'Date sortie')),exitCause:pick(r,'Cause sortie'),comment:pick(r,'Commentaires','Commentaire'),raw:r}}).filter(x=>x.ede&&x.animalId);
  const intro=sheetObjects(w,'INTRODUCTIONS').map((r,i)=>{const ede=digits(pick(r,'N° cheptel','N° EDE')),animalId=digits(pick(r,'N° bovin','Animal'));return{id:key(ede,animalId,i),dept:Number(pick(r,'Dépt')),ede,animalId,entryDate:parseFrenchDate(pick(r,'Date entrée','Date introduction')),origin:pick(r,'Provenance','Cheptel provenance'),control:pick(r,'Contrôle','Analyse'),result:pick(r,'Résultat'),comment:pick(r,'Commentaires','Commentaire'),raw:r}}).filter(x=>x.ede||x.animalId);
  for(const [s,arr] of [['herds',herds],['campaigns',campaigns],['nonnegatives',nns],['descendants',desc],['introductions',intro]]){await db.clear(s);await db.bulkPut(s,arr)}
  const camp=pick(sheetObjects(w,'PARAMETRES')[1]||{},'Valeur')||currentCampaignDefault(); if(/^\d{4}\/\d{4}$/.test(camp))await setMeta('currentCampaign',camp);
}
function parseDelimited(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());if(!lines.length)return[];const sep=(lines[0].match(/;/g)||[]).length>(lines[0].match(/,/g)||[]).length?';':',';const parseLine=line=>{const out=[];let cur='',q=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'){if(q&&line[i+1]==='"'){cur+='"';i++}else q=!q}else if(ch===sep&&!q){out.push(cur);cur=''}else cur+=ch}out.push(cur);return out.map(v=>v.replace(/^="(.*)"$/,'$1').trim())};const headers=parseLine(lines[0]);return lines.slice(1).map(l=>{const a=parseLine(l),o={};headers.forEach((h,i)=>o[h]=a[i]??'');return o})}
async function importAnimals(file,dept){const text=await file.text(),rows=parseDelimited(text);const arr=rows.map((r,i)=>{const animalId=digits(pick(r,'Identifiant bovin'));if(!animalId)return null;const exitDate=parseFrenchDate(pick(r,'Date sortie'));const code=pick(r,'Cause de sortie');const cm={E:'Élevage',B:'Boucherie',M:'Mort',H:'Héritage',C:'Autoconsommation'};return{id:key(dept,animalId),dept,animalId,motherId:digits(pick(r,'Numéro mère')),ede:digits(pick(r,'Exploitation')),birthDate:parseFrenchDate(pick(r,'Date naissance')),exitDate,presence:exitDate?'Sorti':'Présent',exitCause:cm[code]||code,workNo:pick(r,'Numéro travail'),name:pick(r,'Nom'),sex:pick(r,'Sexe'),raw:r}}).filter(Boolean);const old=state.animals.filter(a=>Number(a.dept)!==dept);await db.clear('animals');await db.bulkPut('animals',[...old,...arr])}
async function importAnalysis(file,dept){const text=await file.text(),rows=parseDelimited(text);const arr=rows.map((r,i)=>{if(pick(r,'Code maladie')!=='PTB'||pick(r,"Base de l'analyse")!=='S'||pick(r,"Type d'analyse")!=='I'||pick(r,'Contexte')!=='P')return null;const ede=digits(pick(r,"N° d'exploitation")),sampleDate=parseFrenchDate(pick(r,'Date de prélèvement')),camp=campaignFromDate(sampleDate);if(!ede||!camp)return null;return{id:key(dept,ede,camp,pick(r,"N° incrément du lot d'analyse")||i,pick(r,'Numéro du dossier laboratoire')),dept,ede,campaign:camp,sampleDate,tested:num(pick(r,"Nombre d'analyse ou de prélèvements effectués")),positive:num(pick(r,"Nombre d'analyses positives")),animalsConcerned:num(pick(r,"Nombre d'animaux concernés par l'analyse")),lastUpdate:parseFrenchDate(pick(r,'Date de la dernière mise à jour')),labFile:pick(r,'Numéro du dossier laboratoire'),raw:r}}).filter(Boolean);const keep=state.analysisLots.filter(x=>Number(x.dept)!==dept||!arr.some(n=>n.campaign===x.campaign));await db.clear('analysisLots');await db.bulkPut('analysisLots',[...keep,...arr])}

function runExport(type){let rows=[],headers=[];const herdRows=state.herds.map(h=>({Département:h.dept,EDE:h.ede,Nom:h.name,Commune:h.commune,Mode:h.mode,Qualification:h.currentQualification,Vétérinaire:h.vet}));if(type==='engages'){rows=herdRows;headers=Object.keys(rows[0]||{})}else if(type.startsWith('garantie')||type.startsWith('ass')){const guarantee=type.startsWith('garantie'),dept=type.endsWith('32')?32:type.endsWith('65')?65:null;rows=herdRows.filter((r,i)=>{const h=state.herds[i];return norm(h.mode).includes(guarantee?'garantie':'assain')&&(!dept||Number(h.dept)===dept)});headers=Object.keys(herdRows[0]||{})}else if(type==='bilan'){rows=[balance()];headers=Object.keys(rows[0])}else if(type==='positifs'){rows=[...analysisAggregate().values()].filter(a=>a.positive>0).map(a=>({EDE:a.ede,Nom:herdByEde(a.ede)?.name||'',Dépistés:a.tested,Négatifs:a.negative,Positifs:a.positive,Date:fmtDate(a.last),Statut:a.status}));headers=Object.keys(rows[0]||{EDE:'',Nom:'',Dépistés:'',Négatifs:'',Positifs:'',Date:'',Statut:''})}else if(type==='nonnegpresent'){const ai=animalIndex();rows=state.nonnegatives.filter(n=>(ai.get(String(n.animalId))?.presence||n.presence)==='Présent').map(n=>({...n,animalName:ai.get(String(n.animalId))?.name||''}));headers=['campaign','dept','ede','animalId','animalName','result','date','comment']}else if(type==='descendants'){rows=state.descendants;headers=['dept','ede','motherId','animalId','birthDate','presence','exitDate','exitCause','comment']}else if(type==='introductions'){rows=state.introductions;headers=['dept','ede','animalId','entryDate','origin','control','result','comment']}else if(type==='animalsAll'||type==='animalsPresent'){const engaged=new Set(state.herds.map(h=>String(h.ede)));rows=state.animals.filter(a=>engaged.has(String(a.ede))&&(type==='animalsAll'||a.presence==='Présent')).map(a=>({Département:a.dept,EDE:a.ede,'N° bovin':a.animalId,'N° travail':a.workNo,Nom:a.name,Sexe:a.sex,'Date naissance':fmtDate(a.birthDate),Présence:a.presence,'Date sortie':fmtDate(a.exitDate),'Cause sortie':a.exitCause,'N° mère':a.motherId}));headers=Object.keys(rows[0]||{'Département':'','EDE':'','N° bovin':''})}else if(type==='campaignFollowup'){const ag=analysisAggregate();rows=state.campaigns.filter(c=>c.campaign===state.campaign).map(c=>{const h=herdByEde(c.ede),a=ag.get(String(c.ede)),p=managementProposal(c.ede,a);return{EDE:c.ede,Nom:h?.name||c.name,Mode:h?.mode||c.mode,'Résultat reçu':a?'Oui':'Non','Dépistés':a?.tested||'',Positifs:a?.positive||'',Statut:a?.status||'En attente','Qualification proposée':p.qualification,'N+1 proposé':p.nextScreening,'Cas référentiel':p.caseRef}});headers=Object.keys(rows[0]||{EDE:'',Nom:''})};download(`PTB_${type}_${state.campaign.replace('/','-')}.csv`,toCSV(rows,headers),'text/csv;charset=utf-8')}

async function makeBackup(){const obj={version:APP_VERSION,createdAt:new Date().toISOString(),meta:state.meta};for(const s of STORES.filter(x=>x!=='meta'))obj[s]=await db.all(s);download(`PTB_GDS_backup_${today()}.json`,JSON.stringify(obj,null,2),'application/json')}
async function restoreBackup(file){if(!file)return;const obj=JSON.parse(await file.text());for(const s of STORES.filter(x=>x!=='meta')){await db.clear(s);if(Array.isArray(obj[s]))await db.bulkPut(s,obj[s])}if(obj.meta)for(const [k,v] of Object.entries(obj.meta))await setMeta(k,v);await loadState();render();toast('Sauvegarde restaurée')}
async function resetDb(){if(!confirm('Effacer toutes les données locales de l’application ?'))return;for(const s of STORES)await db.clear(s);await loadState();render()}

async function supabaseRequest(path,opts={}){const url=state.meta.supabaseUrl,keyv=state.meta.supabaseKey;if(!url||!keyv)throw new Error('Supabase non configuré');const r=await fetch(url+'/rest/v1/'+path,{...opts,headers:{apikey:keyv,Authorization:'Bearer '+keyv,'Content-Type':'application/json',Prefer:'resolution=merge-duplicates,return=minimal',...(opts.headers||{})}});if(!r.ok)throw new Error(await r.text());return r.status===204?null:r.json()}
async function pushSupabase(){try{await setMeta('supabaseUrl',$('#sbUrl').value.trim().replace(/\/$/,''));await setMeta('supabaseKey',$('#sbKey').value.trim());const records=[];for(const s of STORES.filter(x=>x!=='meta'))for(const o of await db.all(s))records.push({dataset:s,id:o.id,payload:o,updated_at:new Date().toISOString()});for(let i=0;i<records.length;i+=500)await supabaseRequest('ptb_records?on_conflict=dataset,id',{method:'POST',body:JSON.stringify(records.slice(i,i+500))});for(const [k,v] of Object.entries(state.meta))await supabaseRequest('ptb_records?on_conflict=dataset,id',{method:'POST',body:JSON.stringify([{dataset:'meta',id:k,payload:{id:k,value:v},updated_at:new Date().toISOString()}])});toast('Synchronisation envoyée')}catch(e){console.error(e);toast('Supabase : '+e.message)}}
async function pullSupabase(){try{await setMeta('supabaseUrl',$('#sbUrl').value.trim().replace(/\/$/,''));await setMeta('supabaseKey',$('#sbKey').value.trim());const rows=await supabaseRequest('ptb_records?select=dataset,id,payload',{method:'GET'});for(const s of STORES)await db.clear(s);for(const r of rows){const target=r.dataset==='meta'?'meta':r.dataset;if(STORES.includes(target))await db.put(target,r.payload)}await loadState();render();toast('Données Supabase récupérées')}catch(e){console.error(e);toast('Supabase : '+e.message)}}

async function init(){await db.open();await loadState();populateCampaignSelector();$('#globalCampaign').onchange=async e=>{state.campaign=e.target.value;await setMeta('currentCampaign',state.campaign);render()};$('#btnBackup').onclick=makeBackup;$$('.nav-btn').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render()});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});render()}
init().catch(e=>{$('#app').innerHTML=`<div class="error">Erreur au démarrage : ${esc(e.message)}</div>`;console.error(e)});
